gBW(){return"\u0644\u0645 \u0623\u0641\u0647\u0645 \u0630\u0644\u0643 \u062a\u0645\u0627\u0645\u064b\u0627. \u064a\u0645\u0643\u0646\u0643 \u0623\u0646 \u062a\u0633\u0623\u0644: \u0643\u064a\u0641 \u0643\u0627\u0646 \u0646\u0648\u0645\u064a\u060c \u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u064a\u0648\u0645\u060c \u0646\u0628\u0636\u064a\u060c \u062a\u0639\u0627\u0641\u064a\u0651\u060c \u062d\u0645\u0644\u064a\u060c \u062a\u0648\u062a\u0631\u064a\u060c \u062a\u062e\u0637\u064a\u0637 \u0642\u0644\u0628\u064a\u060c \u0639\u0645\u0631\u064a \u0627\u0644\u0628\u064a\u0648\u0644\u0648\u062c\u064a\u060c \u062e\u0637\u0648\u0627\u062a\u064a\u060c \u0623\u0648 \u062a\u0645\u0631\u064a\u0646 \u064a\u0646\u0627\u0633\u0628\u0646\u064a."},
gO3(){return"\u0645\u0627 \u062a\u0635\u0641\u0647 \u0642\u062f \u064a\u0643\u0648\u0646 \u062d\u0627\u0644\u0629 \u0637\u0627\u0631\u0626\u0629. \u0627\u062a\u0635\u0644 \u0628\u0640 112 \u0641\u0648\u0631\u064b\u0627 \u0623\u0648 \u062a\u0648\u062c\u0651\u0647 \u0625\u0644\u0649 \u0623\u0642\u0631\u0628 \u0642\u0633\u0645 \u0637\u0648\u0627\u0631\u0626. \u0644\u0627 \u064a\u0645\u0643\u0646 \u0644\u0644\u0633\u0648\u0627\u0631 \u0648\u0644\u0627 \u0644\u0647\u0630\u0627 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u062a\u0642\u064a\u064a\u0645 \u062d\u0627\u0644\u0629 \u0637\u0627\u0631\u0626\u0629."},
gOb(){return"\u0644\u0627 \u0623\u0633\u062a\u0637\u064a\u0639 \u0627\u0644\u062a\u0634\u062e\u064a\u0635 \u0623\u0648 \u0627\u0642\u062a\u0631\u0627\u062d \u0623\u062f\u0648\u064a\u0629 \u0623\u0648 \u062c\u0631\u0639\u0627\u062a\u061b \u064a\u064f\u0631\u062c\u0649 \u0627\u0633\u062a\u0634\u0627\u0631\u0629 \u0637\u0628\u064a\u0628\u0643. \u064a\u0645\u0643\u0646\u0646\u064a \u0623\u0646 \u0623\u062e\u0628\u0631\u0643 \u0628\u0645\u0627 \u0623\u0631\u0627\u0647 \u0641\u064a \u0628\u064a\u0627\u0646\u0627\u062a\u0643."},
gBU(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0628\u064a\u0627\u0646\u0627\u062a \u0643\u0627\u0641\u064a\u0629 \u062d\u0648\u0644 \u0647\u0630\u0627 \u0628\u0639\u062f. \u0643\u0644\u0645\u0627 \u0627\u0631\u062a\u062f\u064a\u062a \u0627\u0644\u0633\u0648\u0627\u0631 \u0648\u0632\u0627\u0645\u0646\u062a\u0647\u060c \u0627\u0633\u062a\u0637\u0639\u062a \u0623\u0646 \u0623\u062e\u0628\u0631\u0643 \u0623\u0643\u062b\u0631."},
