Oj(a){return"\u0646\u0645\u062a \u0623\u0642\u0644 \u0645\u0646 \u062d\u0627\u062c\u062a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 "+a+"\u061b \u062d\u0627\u0648\u0644 \u0623\u0646 \u062a\u0646\u0627\u0645 \u0623\u0628\u0643\u0631 \u0642\u0644\u064a\u0644\u064b\u0627 \u0627\u0644\u0644\u064a\u0644\u0629."},
